# 判据：第 i 个方程只能依赖 x1..xi 与 x_(i+1)，且 x_(i+1) 必须线性出现；
#       u 只允许出现在最后一个方程，且线性出现。
# 三项检查全部用差分算出来，不依赖人工读方程：
#   g_i      = d f_i / d x_(i+1)          中心差分，必须非零
#   二阶差商 = d2 f_i / d x_(i+1)^2       必须为零，即线性出现
#   越界泄漏 = max_{j>i+1} |d f_i/d x_j|  必须为零，即下三角

def perturb(f, x, u, idx, h):
    if idx == "u":
        return f(x, u + h)
    xp = np.array(x, dtype=float)
    xp[idx] += h
    return f(xp, u)

def partial(f, x, u, idx, i, h=1e-5):
    return (perturb(f, x, u, idx, h)[i] - perturb(f, x, u, idx, -h)[i]) / (2*h)

def second_partial(f, x, u, idx, i, h=2e-3):
    return (perturb(f, x, u, idx, h)[i] - 2*f(x, u)[i] + perturb(f, x, u, idx, -h)[i]) / h**2

def structure_report(name, f, n, xbar, ubar=0.0, tol=1e-4):
    print()
    print("【" + name + "】  n = " + str(n))
    print("  方程   通道      g_i        二阶差商     越界泄漏      判定")
    ok_all = True
    for i in range(n):
        last = (i == n - 1)
        chan = "u" if last else i + 1
        g = partial(f, xbar, ubar, chan, i)
        lin = abs(second_partial(f, xbar, ubar, chan, i))
        leak = 0.0
        for j in range(i + 2, n):
            leak = max(leak, abs(partial(f, xbar, ubar, j, i)))
        if not last:
            leak = max(leak, abs(partial(f, xbar, ubar, "u", i)))
        ok = (abs(g) > tol) and (lin < tol*max(1.0, abs(g))) and (leak < tol)
        ok_all = ok_all and ok
        why = []
        if abs(g) <= tol:
            why.append("g=0")
        if lin >= tol*max(1.0, abs(g)):
            why.append("非线性")
        if leak >= tol:
            why.append("越界依赖")
        print("  " + str(i+1) + "      " + ("u " if last else "x" + str(i+2))
              + "   " + ("%.4f" % g).rjust(9) + "   " + ("%.2e" % lin).rjust(10)
              + "   " + ("%.2e" % leak).rjust(10) + "      "
              + ("严格反馈" if ok else "违反(" + ",".join(why) + ")"))
    print("  => " + ("结构合格，可用反步法" if ok_all else "结构不合格，反步法不直接适用"))
    return ok_all

# S1 标准二阶机械系统（单摆型）
def s1(x, u):
    return np.array([x[1], -3.0*np.sin(x[0]) - x[1] + u])

# S2 柔性关节机器人：Jl=1, Jm=0.5, K=200, Bl=1, Bm=0.5，状态 (q, q_dot, theta, theta_dot)
Jl, Jm, Kk, Bl, Bm = 1.0, 0.5, 200.0, 1.0, 0.5
def s2(x, u):
    return np.array([x[1],
                     (-Bl*x[1] - Kk*(x[0] - x[2])) / Jl,
                     x[3],
                     (-Bm*x[3] - Kk*(x[2] - x[0]) + u) / Jm])

# S3 Boost 变换器平均模型：x1 = VC, x2 = iL, u = 占空比
L, C, R, Vin = 1e-3, 1e-4, 10.0, 12.0
def s3(x, u):
    return np.array([(1-u)*x[1]/C - x[0]/(R*C),
                     -(1-u)*x[0]/L + Vin/L])

# S4 纯反馈系统：x2 以三次方出现
def s4(x, u):
    return np.array([x[0] + x[1]**3, u])

structure_report("S1 二阶机械系统 x1'=x2, x2'=-3sin(x1)-x2+u", s1, 2, [0.6, -0.3], 0.2)
structure_report("S2 柔性关节机器人 (Jl,Jm,K,Bl,Bm)=(1,0.5,200,1,0.5)", s2, 4,
                 [0.4, 0.2, 0.5, -0.1], 1.5)
structure_report("S3 Boost 变换器 (x1=VC, x2=iL, u=占空比)", s3, 2, [24.0, 2.0], 0.4)
structure_report("S4 纯反馈 x1'=x1+x2^3, x2'=u", s4, 2, [0.5, 0.4], 0.1)

print()
print("结论：S2 在自然状态排序 (q, q_dot, theta, theta_dot) 下已经是严格反馈形式，")
print("      不需要任何坐标变换；S3 因为 u 同时进入两个方程（且与状态相乘）而不合格；")
print("      S4 因为 x2 以三次方出现而不合格。")

